function simplePanel(title,body,buttons=[]){modal.replaceChildren();modal.hidden=false;modalKind='panel';const box=document.createElement('div');box.className='simple-panel';const h=document.createElement('h1');h.textContent=title;box.append(h);const content=document.createElement('div');content.innerHTML=body;box.append(content);for(const [text,action] of buttons){const b=document.createElement('button');b.textContent=text;b.dataset.action=action;box.append(b);}modal.append(box);closeButton();}
function report(){if(engine.state.pending)return;simplePanel('棋盘报告',`<div class="report-scroll">${engine.state.report.length?engine.state.report.map(r=>`<div class="report-item">${escape(r.message)}</div>`).join(''):'<p>还没有棋盘事件</p>'}</div>`);}
async function handleAction(action){
 if(milestoneWidgets?.handle(action))return;
 if(action==='roll'){if(auto){auto=false;clearTimeout(autoTimer);if(!busy)scene.stopFollow();toast('已停止自动投点');return;}return roll();}
 if(action==='bet'){if(busy)return;engine.nextBet();update();return;}
 if(action==='close')return close();
 if(action==='build')return showBuild();if(action==='gacha')return showGacha();
 if(action==='chance-confirm')return chanceConfirm();if(action==='prison-roll')return prisonRoll();
 if(action==='dismiss'){engine.dismiss();hideModal();return;}
 if(action==='report')return report();
 if(action==='menu'){if(engine.state.pending)return;auto=false;simplePanel('蜡笔小新',`<p>第 ${engine.state.map} 张地图</p><p>金币 ${format(engine.state.coins)} · 骰子 ${format(engine.state.dice)}</p><p class="local-note">当前进度保存在此设备。好友对手为本地角色。</p>`,[['棋盘报告','report'],['重新开始','reset-confirm']]);return;}
 if(action==='album'){simplePanel('画册',`<p>已收集贴纸 ${engine.state.stickers || 0} 张</p><p>建造获得扭蛋币，扭蛋可获得贴纸奖励。</p>`);return;}
 if(action==='fund'){const result=engine.openFund();if(result.error)toast(result.error);else{update();floatReward('+'+format(result.coins));toast('领取存钱罐 '+format(result.coins)+' 美金');}return;}
 if(action==='draw-gacha'){const result=engine.drawGacha();if(result.error){toast(result.error);return;}showGacha();update();toast(result.coins?'美金 +'+format(result.coins):result.dice?'骰子 +'+result.dice:'获得 '+result.card+' 张贴纸');return;}
 if(action==='next-map'){if(!engine.canUpgradeMap)return;busy=true;try{const base=window.GAME_DATA.maps[Math.min(engine.state.map,2)].baseId;await scene.ensureMap(base);if(engine.upgradeMap()){dice3d.clear();hideModal();scene.follow(0,true);scene.setPiece(0,piece);toast('进入新地图，获得50骰子和10,000美金');}}catch(error){toast('地图加载失败，请重试');console.error(error);}finally{busy=false;update();}return;}
 if(action==='switch-target'){const p=engine.state.pending;if(p?.kind!=='attack')return;engine.changeOpponent((p.target+1)%3);showAttack();save();return;}
 if(action.startsWith('build:')){const result=engine.build(Number(action.split(':')[1]));if(result?.error)toast(result.error);else{showBuild();update();toast(result.complete?'地图建筑已全部完成':'建筑升级至 '+result.level+' 级');}return;}
 if(action.startsWith('attack:')){if(eventClosing||engine.state.pending?.kind!=='attack')return;const p={...engine.state.pending};const result=engine.attack(Number(action.split(':')[1]));if(result?.error){toast(result.error);return;}if(!result)return;const activityChange=activities.attack(result.blocked,p.bet,'attack:'+engine.state.turns);save();milestoneWidgets.changed(activityChange);showAttack(result,p.target,p.bet);return;}
 if(action==='event-reward-close'){hideModal();return;}
 if(action.startsWith('blind:')){if(eventClosing||engine.state.pending?.kind!=='blind')return;const p=engine.state.pending,index=Number(action.split(':')[1]),result=engine.openBlind(index);if(!result)return;save();if(result.finished){const activityChange=activities.blind(result.symbol,p.bet,'blind:'+engine.state.turns);save();milestoneWidgets.changed(activityChange);eventClosing=true;showBlindReward(result,p);}else showBlind(index);update();return;}
 if(action==='reset-confirm'){simplePanel('重新开始','<p>清除当前设备上的棋盘进度？</p>',[['确认重新开始','reset']]);return;}
 if(action==='reset'){dice3d.clear();engine.state=engine.fresh();await scene.ensureMap(1);auto=false;hideModal();scene.follow(0,true);update();toast('已重新开始');}
}
let pressTimer=0,longPressed=false;
game.addEventListener('pointerdown',event=>{const el=event.target.closest('[data-action="roll"]');if(!el||busy||!modal.hidden)return;longPressed=false;pressTimer=setTimeout(()=>{longPressed=true;auto=true;toast('自动投点已开启');roll();},550);});
game.addEventListener('pointerup',()=>clearTimeout(pressTimer));game.addEventListener('pointercancel',()=>clearTimeout(pressTimer));game.addEventListener('pointerleave',()=>clearTimeout(pressTimer));
game.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;if(el.dataset.action==='roll'&&longPressed){longPressed=false;return;}if(busy && !['close'].includes(el.dataset.action))return;handleAction(el.dataset.action);});
game.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){const el=event.target.closest('[data-action]');if(el && el.tagName!=='BUTTON'){event.preventDefault();handleAction(el.dataset.action);}}});
async function init(){
 try{
  const loaded=await Promise.all(['assets/scene/building-layout.json','assets/scene/events/strings.json','assets/activities/config.json','assets/scene/milestone/ui.json'].map(n=>fetch(n).then(r=>r.json())));[buildingLayout,eventStrings]=loaded;activities=new MilestoneActivities(engine,loaded[2]);const milestoneAssets=loaded[3],milestoneStrings=await fetch(milestoneAssets.stringsURL).then(r=>r.json());milestoneAssets.nativeListPanel=await fetch(milestoneAssets.referenceSkinImages.bg_common_list02.nativeComponentURL).then(r=>r.json());await document.fonts.load('24px ShinOriginal');makeMain();scene=new OriginalScene($('#board'),window.GAME_DATA,ui,engine.mapConfig.baseId);await scene.load();coinRewards=new OriginalCoinRewards(scene,ui,$('#float-layer'));await coinRewards.load();dice3d=new OriginalDice(scene,game);await dice3d.load();scene.onDraw=()=>{milestoneWidgets?.drawPickups();if(scene.pieceProfile){const v=scene.pieceProfile.viewport;piece.style.width=(v.width*.0024*1624/(2*scene.zoom))+'px';piece.style.height=(v.height*.0024*1624/(2*scene.zoom))+'px';}if(!dice3d.playing)dice3d.redraw();const f=$('#world-ui [data-action="fund"]');if(f){const p=scene.project(0,.084,2.1);f.style.left=p.x+'px';f.style.top=(p.y-45)+'px';}};scene.onMotion=(animation,options)=>{if(animation==='idle')relaxRemaining=10+Math.random()*10;play(animation,options);};scene.onDirection=(to)=>{const d=scene.direction(to);facing=d.back?'b':'f';$('#spine').style.transform=`scale(${d.flip?-1:1},${Math.cos(35*Math.PI/180)})`;if(!currentAnimation.includes('jump'))play(currentAnimation?.replace(/_[fb]$/,'')||'idle');};scene.onDirection(engine.state.position);scene.position=engine.state.position;scene.follow(engine.state.position,true);scene.draw(engine.state);scene.setPiece(engine.state.position,piece);milestoneWidgets=new MilestoneWidgets({ui,engine,main:mainView,scene,show:(name,options,kind)=>{auto=false;clearTimeout(autoTimer);return showModal(name,options,kind);},hide:hideModal,save,update,toast,fly:flyEventIcon,busy:()=>busy},activities,milestoneAssets,milestoneStrings);milestoneWidgets.mount();scene.requestFrame();
  player=new spine.SpinePlayer('spine',{skeleton:'assets/spine/shin/1_body.skel',atlas:'assets/spine/shin/1_body.atlas',animation:'idle_'+facing,showControls:false,showLoading:false,interactive:false,alpha:true,backgroundColor:'#00000000',premultipliedAlpha:true,viewport:{...scene.pieceProfile.viewport,padLeft:0,padRight:0,padTop:0,padBottom:0},error:(p,message)=>{console.error('原Spine加载失败',message);toast('角色动画加载失败，请刷新重试');}});
  const v=scene.pieceProfile.viewport;piece.style.width=(v.width*.0024*1624/11)+'px';piece.style.height=(v.height*.0024*1624/11)+'px';piece.style.transform=`translate(${v.x/v.width*100}%,${-(v.y+v.height)/v.height*100}%)`;$('#spine').style.transformOrigin=`${-v.x/v.width*100}% ${(v.y+v.height)/v.height*100}%`;
  await new Promise((resolve,reject)=>{const deadline=performance.now()+15000;const ready=()=>{if(player.animationState){player.animationState.timeScale=1.5;player.animationState.data.defaultMix=.2;currentAnimation='idle_'+facing;resolve();}else if(performance.now()>deadline)reject(new Error('小新动画加载超时'));else requestAnimationFrame(ready);};ready();});
  update();$('#loading').hidden=true;if(engine.state.pending)showPending();
  window.__SHIN={engine,ui,scene,dice3d,coinRewards,activities,milestoneWidgets,get player(){return player;},get busy(){return busy;},get auto(){return auto;},showPending,showBuild,handleAction};
  setInterval(()=>{if(engine.restoreDice())update();},30000);
  let relaxTick=performance.now();setInterval(()=>{const now=performance.now(),dt=Math.min(1,(now-relaxTick)/1000);relaxTick=now;if(!currentAnimation.startsWith('idle'))return;relaxRemaining-=dt;if(relaxRemaining>0||busy||!modal.hidden||engine.state.pending)return;relaxRemaining=10+Math.random()*10;const name='relax_'+facing,duration=player.skeleton.data.findAnimation(name).duration/1.5;play('relax',{loop:false,speed:1.5});setTimeout(()=>{if(currentAnimation.startsWith('relax')&&!scene.moving)play('idle');},duration*1000);},100);
 }catch(error){console.error(error);$('#loading').innerHTML='<div>加载失败</div><span>请刷新重试</span>';}
}
init();